USE ieee.std_logic_1164.all;
USE ieee.numeric_std.all;


--  Entity Declaration

ENTITY CNTRL IS
-- {{ALTERA_IO_BEGIN}} DO NOT REMOVE THIS LINE!
PORT
(
	RST : IN STD_LOGIC;
	INCR : IN STD_LOGIC;
	DOWN : IN STD_LOGIC;
	UP : IN STD_LOGIC;
	CLK : IN STD_LOGIC;
	EN_ALL : IN STD_LOGIC;
	DUTY_EN : IN STD_LOGIC;
	
	D_OUT : OUT UNSIGNED(7 DOWNTO 0);
	FTW_OUT : OUT UNSIGNED(31 DOWNTO 0);

	ONE_OUT : OUT UNSIGNED(3 DOWNTO 0);
	TEN_OUT : OUT UNSIGNED(3 DOWNTO 0);
	HUNDRED_OUT : OUT UNSIGNED(3 DOWNTO 0);
	THOUSAND_OUT : OUT UNSIGNED(3 DOWNTO 0);
	Ten_THOUSAND_OUT : OUT UNSIGNED(3 DOWNTO 0)
	
