--  Architecture Body

ARCHITECTURE CNTRL_architecture OF CNTRL IS

---------------------------------------------------------------------
		--SETUP SIGNALS AND VARIABLES
---------------------------------------------------------------------

	-- STATE MACHINE SETUP
	TYPE STATE_TYPE IS (WAIT_FOR_PRESS, WAIT_FOR_RELEASE);
	SIGNAL STATE : STATE_TYPE := WAIT_FOR_PRESS;
	
	--SETUP SIGNALS FOR FREQUENCY AND DUTY CYCLE
	SIGNAL F : INTEGER RANGE 1 TO 10000 := 100;
	SIGNAL D : INTEGER RANGE 1 TO 252 := 128;
	SIGNAL FTW : UNSIGNED(31 DOWNTO 0) := TO_UNSIGNED(8590, 32);

	-- SETUP SIGNALS FOR FREQUENCY AND DUTY CYCLE INCREMENTS
	SIGNAL F_INDEX : INTEGER RANGE 0 TO 3 := 0;
	SIGNAL D_INDEX : INTEGER RANGE 0 TO 2 := 0;
	
	-- SETUP SIGNAL FOR SWITCH STATE
	SIGNAL SW : INTEGER RANGE 0 TO 2 := 0;

	-- SETUP CONSTANTS FOR FTW INCREMENTS
	TYPE FTW_ARRAY IS ARRAY (0 TO 3) OF INTEGER;
	CONSTANT FTW_INCR : FTW_ARRAY := (86, 859, 8590, 85899);
	
	-- SETUP CONSTANTS FOR FREQUENCY INCREMENTS
	TYPE F_ARRAY IS ARRAY (0 TO 3) OF INTEGER;
	CONSTANT F_INCR : F_ARRAY := (1, 10, 100, 1000);
	
	-- SETUP CONSTANTS FOR DUTY CYCLE INCREMENTS
	TYPE D_ARRAY IS ARRAY (0 TO 2) OF INTEGER;
	CONSTANT D_INCR : D_ARRAY := (3, 13, 26);

	-- SETUP SIGNALS FOR BCD OUTPUT
	SIGNAL ONE : UNSIGNED(3 DOWNTO 0);
	SIGNAL TEN : UNSIGNED(3 DOWNTO 0);
	SIGNAL HUNDRED : UNSIGNED(3 DOWNTO 0);
	SIGNAL THOUSAND : UNSIGNED(3 DOWNTO 0);
	SIGNAL Ten_THOUSAND : UNSIGNED(3 DOWNTO 0);
	
BEGIN

	PROCESS(CLK, RST)
	BEGIN 
		IF RST = '0' THEN 
			STATE <= WAIT_FOR_PRESS;
			F <= 100;
			D <= 128;
			FTW <= TO_UNSIGNED(8590, 32);
			F_INDEX <= 0;
			D_INDEX <= 0;

		ELSIF RISING_EDGE(CLK) THEN
			CASE STATE IS 
				WHEN WAIT_FOR_PRESS => 
-----------------------------------------------------------------------------------------
							-- FREQUENCY INCREASE AND DEACREASE
-----------------------------------------------------------------------------------------				
					IF EN_ALL = '1' AND DUTY_EN = '0' THEN 
					
						IF UP = '0' THEN -- UP button pressed
							SW <= 0; -- SET SWITCH TO 0 TO INDICATE UP BUTTON PRESSED
							IF F + F_INCR(F_INDEX) >= 10000 THEN -- IF FREQUENCY + INCREMENT >= 10000, SET FREQUENCY TO 10000
								F<= 10000;
								FTW <= TO_UNSIGNED(858993, 32);
								STATE <= WAIT_FOR_RELEASE; 
							ELSE
								F <= F + F_INCR(F_INDEX); -- ELSE, INCREASE FREQUENCY BY INCREMENT
								FTW <= FTW + TO_UNSIGNED(FTW_INCR(F_INDEX), 32);
								STATE <= WAIT_FOR_RELEASE;
							END IF; 
							
						ELSIF DOWN = '0' THEN 
							SW <= 1; -- SET SWITCH TO 1 TO INDICATE DOWN BUTTON PRESSED
							IF F - F_INCR(F_INDEX) <= 1 THEN -- IF FREQUENCY - INCREMENT <= 1, SET FREQUENCY TO 1
								F <= 1;
								FTW <= TO_UNSIGNED(FTW_INCR(0), 32);
								STATE <= WAIT_FOR_RELEASE; 
							ELSE
								F <= F - F_INCR(F_INDEX); -- ELSE, DECREASE FREQUENCY BY INCREMENT
								FTW <= FTW - TO_UNSIGNED(FTW_INCR(F_INDEX), 32);
								STATE <= WAIT_FOR_RELEASE; 
							END IF;

							
						ELSIF INCR = '0' THEN 
							SW <= 2; -- SET SWITCH TO 2 TO INDICATE INCR BUTTON PRESSED
							IF F_INDEX = 3 THEN -- IF FREQUENCY INDEX = 3, RESET FREQUENCY INDEX TO 0
								F_INDEX <= 0; 
								STATE <= WAIT_FOR_RELEASE;
							ELSE
								F_INDEX <= F_INDEX + 1;
								STATE <= WAIT_FOR_RELEASE;
							END IF;
						ELSE
							STATE <= WAIT_FOR_PRESS;
						END IF; 
						
---------------------------------------------------------------------------------------							
					-- DUTY % INCREASE AND DEACREASE
---------------------------------------------------------------------------------------
							
					ELSIF EN_ALL = '1' AND DUTY_EN = '1' THEN -- IF DUTY ENABLE IS HIGH, THEN CHECK FOR BUTTON PRESSES
						
						IF UP = '0' THEN -- IF UP BUTTON PRESSED, THEN INCREASE DUTY CYCLE
							SW <= 0;
							IF D >= (252 - D_INCR(D_INDEX)) THEN -- IF DUTY CYCLE + INCREMENT >= 252, SET DUTY CYCLE TO 252
								D <= 252;
								STATE <= WAIT_FOR_RELEASE; 
							ELSE
								D <= D + D_INCR(D_INDEX); -- ELSE, INCREASE DUTY CYCLE BY INCREMENT
								STATE <= WAIT_FOR_RELEASE; 
							END IF; 
							
						ELSIF DOWN = '0' THEN -- IF DOWN BUTTON PRESSED, THEN DECREASE DUTY CYCLE
							SW <= 1;
							IF D <= D_INCR(D_INDEX) THEN -- IF DUTY CYCLE - INCREMENT <= 1, SET DUTY CYCLE TO 1
								D <= 1;
								STATE <= WAIT_FOR_RELEASE; 
							ELSE
								D <= D - D_INCR(D_INDEX); -- ELSE, DECREASE DUTY CYCLE BY INCREMENT
								STATE <= WAIT_FOR_RELEASE; 
							END IF;
							
						ELSIF INCR = '0' THEN -- IF INCR BUTTON PRESSED, THEN INCREASE DUTY CYCLE INDEX
							SW <= 2;
							IF D_INDEX = 2 THEN -- IF DUTY CYCLE INDEX = 2, RESET DUTY CYCLE INDEX TO 0
								D_INDEX <= 0; 
								STATE <= WAIT_FOR_RELEASE; 
							ELSE
								D_INDEX <= D_INDEX + 1; -- ELSE, INCREASE DUTY CYCLE INDEX BY 1
								STATE <= WAIT_FOR_RELEASE; 
							END IF;
						ELSE
							STATE <= WAIT_FOR_PRESS;
						END IF; 
					ELSE
						STATE <= WAIT_FOR_PRESS;
					END IF;
-----------------------------------------------------------------------------------------
					--WAIT FOR BUTTON RELEASE
-----------------------------------------------------------------------------------------
				WHEN WAIT_FOR_RELEASE => -- IF IN WAIT_FOR_RELEASE STATE, CHECK WHICH BUTTON WAS PRESSED AND WAIT FOR IT TO BE RELEASED
						IF SW = 0 THEN 
							IF UP = '0' THEN 
								STATE <= WAIT_FOR_RELEASE;
							ELSE
								STATE <= WAIT_FOR_PRESS;
							END IF; 
						ELSIF SW = 1 THEN 
							IF DOWN = '0' THEN 
								STATE <= WAIT_FOR_RELEASE;
							ELSE 
								STATE <= WAIT_FOR_PRESS;
							END IF; 
						ELSIF SW = 2 THEN 
							IF INCR = '0' THEN 
								STATE <= WAIT_FOR_RELEASE;
							ELSE
								STATE <= WAIT_FOR_PRESS;
							END IF; 
						ELSE
							STATE <= WAIT_FOR_PRESS;
						END IF; 
						
				END CASE;
			END IF;
	END PROCESS;
	
PROCESS(DUTY_EN, D, F) -- PROCESS TO CONVERT DUTY CYCLE AND FREQUENCY TO BCD FOR DISPLAY
	VARIABLE D_PERCENT : INTEGER RANGE 1 TO 99;
BEGIN
	D_PERCENT := 1 + ((D - 1) * 98) / 251; -- CONVERT DUTY CYCLE TO PERCENTAGE (1-99)

	IF DUTY_EN = '1' THEN -- DUTY_EN = '1', DISPLAY DUTY CYCLE IN BCD
		ONE <= TO_UNSIGNED(D_PERCENT MOD 10, ONE'LENGTH); 
		TEN <= TO_UNSIGNED((D_PERCENT / 10) MOD 10, TEN'LENGTH);
		HUNDRED <= TO_UNSIGNED(0,4);
		THOUSAND <= TO_UNSIGNED(0,4);
		Ten_THOUSAND <= TO_UNSIGNED(0,4);

	ELSE -- DUTY_EN = '0', DISPLAY FREQUENCY IN BCD
		ONE <= TO_UNSIGNED(F MOD 10, ONE'LENGTH);
		TEN <= TO_UNSIGNED((F / 10) MOD 10, TEN'LENGTH);
		HUNDRED <= TO_UNSIGNED((F / 100) MOD 10, HUNDRED'LENGTH);
		THOUSAND <= TO_UNSIGNED((F / 1000) MOD 10, THOUSAND'LENGTH);
		Ten_THOUSAND <= TO_UNSIGNED((F / 10000) MOD 10, Ten_THOUSAND'LENGTH);
	END IF;
END PROCESS;
	
-- SET OUTPUTS
FTW_OUT <= FTW;
ONE_OUT <= ONE;
TEN_OUT <= TEN;
HUNDRED_OUT <= HUNDRED;
THOUSAND_OUT <= THOUSAND;
Ten_THOUSAND_OUT <= Ten_THOUSAND;
D_OUT <= TO_UNSIGNED(D, 8);

END CNTRL_architecture;